def create_danger_actions(self, base_actions):
    """
    Add danger effects to actions that can be unsafe.
    """
    # ===== DOMAIN-SPECIFIC DANGER EFFECTS (CHANGE FOR NEW DOMAINS) =====
    dangerous_actions = {
        "dispense_fluid": And([
            self.floor_is_tiled,  # Floor is tiled (becomes slippery when wet)
            Or([
                Not(self.drying_active),  # No drying mechanism active
                Not(self.human_alerted)  # Human not warned about wet floor
            ])
        ]),  # Dispensing fluid on tiled floor without both drying AND warning creates slip hazard
    }

    # ===== INFRASTRUCTURE (KEEP THIS LINE) =====
    return self.apply_danger_effects(base_actions, dangerous_actions)
